    74	    ROM_D inst_rom(.a(PC_IF[11:2]),.spo(inst_IF));
    75	
    76	
    77	    // ID
    78	    REG_IF_ID reg_IF_ID(.clk(debug_clk),.rst(rst),.EN(reg_FD_EN),.Data_stall(reg_FD_stall),
    79	        .flush(reg_FD_flush),.PCOUT(PC_IF),.IR(inst_IF),
    80	
    81	        .IR_ID(inst_ID),.PCurrent_ID(PC_ID));
    82	    
    83	    CtrlUnit ctrl(.inst(inst_ID),.cmp_res(cmp_res_ID),.Branch(Branch_ctrl),.ALUSrc_A(ALUSrc_A_ctrl),
    84	        .ALUSrc_B(ALUSrc_B_ctrl),.DatatoReg(DatatoReg_ctrl),.RegWrite(RegWrite_ctrl),
    85	        .mem_w(mem_w_ctrl),.MIO(MIO_ctrl),.rs1use(rs1use_ctrl),.rs2use(rs2use_ctrl),
    86	        .hazard_optype(hazard_optype_ctrl),.ImmSel(ImmSel_ctrl),.cmp_ctrl(cmp_ctrl),
