    88	    
    89	    Regs register(.clk(debug_clk),.rst(rst),.L_S(RegWrite_WB),.R_addr_A(inst_ID[19:15]),
    90	        .R_addr_B(inst_ID[24:20]),.rdata_A(rs1_data_reg),.rdata_B(rs2_data_reg),
    91	        .Wt_addr(rd_WB),.Wt_data(wt_data_WB),
    92	        .Debug_addr(debug_addr[4:0]),.Debug_regs(Debug_regs));
    93	    
    94	    ImmGen imm_gen(.ImmSel(ImmSel_ctrl),.inst_field(inst_ID),.Imm_out(Imm_out_ID));
    95	    
    96	    // TODO: implement — forward mux for rs1 data (register, EX bypass, MEM bypass, or load data)
    97	    MUX4T1_32 mux_forward_A(.I0(32'b0),.I1(32'b0),.I2(32'b0),.I3(32'b0),
    98	        .s(2'b0),.o(rs1_data_ID));
    99	
   100	    // TODO: implement — forward mux for rs2 data (register, EX bypass, MEM bypass, or load data)
   101	    MUX4T1_32 mux_forward_B(.I0(32'b0),.I1(32'b0),.I2(32'b0),.I3(32'b0),
   102	        .s(2'b0),.o(rs2_data_ID));
   103	    
   104	    // TODO: implement — select branch address source (PC or rs1 for JALR)
   105	    MUX2T1_32 mux_branch_ID(.I0(32'b0),.I1(32'b0),.s(1'b0),.o(addA_ID));
   106	
   107	    add_32 add_branch_ID(.a(addA_ID),.b(Imm_out_ID),.c(jump_PC_ID));
   108	
   109	    cmp_32 cmp_ID(.a(rs1_data_ID),.b(rs2_data_ID),.ctrl(cmp_ctrl),.c(cmp_res_ID));
   110	    
   111	    HazardDetectionUnit hazard_unit(.clk(debug_clk),.Branch_ID(Branch_ctrl),.rs1use_ID(rs1use_ctrl),
   112	        .rs2use_ID(rs2use_ctrl),.hazard_optype_ID(hazard_optype_ctrl),.rd_EXE(rd_EXE),
   113	        .rd_MEM(rd_MEM),.rs1_ID(inst_ID[19:15]),.rs2_ID(inst_ID[24:20]),.rs2_EXE(rs2_EXE),.cmu_stall(cmu_stall),
   114	        .PC_EN_IF(PC_EN_IF),.reg_FD_EN(reg_FD_EN),.reg_FD_stall(reg_FD_stall),
   115	        .reg_FD_flush(reg_FD_flush),.reg_DE_EN(reg_DE_EN),.reg_DE_flush(reg_DE_flush),
   116	        .reg_EM_EN(reg_EM_EN),.reg_EM_flush(reg_EM_flush),.reg_MW_EN(reg_MW_EN),
   117	        .forward_ctrl_ls(forward_ctrl_ls),.forward_ctrl_A(forward_ctrl_A),
   118	        .forward_ctrl_B(forward_ctrl_B));
   119	
   120	
   121	    // EX
   122	    REG_ID_EX reg_ID_EX(.clk(debug_clk),.rst(rst),.EN(reg_DE_EN),.flush(reg_DE_flush),.IR_ID(inst_ID),
   123			.PCurrent_ID(PC_ID),.rs1_addr(inst_ID[19:15]),.rs2_addr(inst_ID[24:20]),.rs1_data(rs1_data_ID),
   124			.rs2_data(rs2_data_ID),.Imm32(Imm_out_ID),.rd_addr(inst_ID[11:7]),.ALUSrc_A(ALUSrc_A_ctrl),
   125			.ALUSrc_B(ALUSrc_B_ctrl),.ALUC(ALUControl_ctrl),.DatatoReg(DatatoReg_ctrl),
   126	        .RegWrite(RegWrite_ctrl),.WR(mem_w_ctrl),.u_b_h_w(inst_ID[14:12]),.MIO(MIO_ctrl),
   127	
   128	        .PCurrent_EX(PC_EXE),.IR_EX(inst_EXE),.rs1_EX(rs1_EXE),.rs2_EX(rs2_EXE),
   129	        .A_EX(rs1_data_EXE),.B_EX(rs2_data_EXE),.Imm32_EX(Imm_EXE),.rd_EX(rd_EXE),
   130	        .ALUSrc_A_EX(ALUSrc_A_EXE),.ALUSrc_B_EX(ALUSrc_B_EXE),.ALUC_EX(ALUControl_EXE),
   131	        .DatatoReg_EX(DatatoReg_EXE),.RegWrite_EX(RegWrite_EXE),.WR_EX(mem_w_EXE),
   132	        .u_b_h_w_EX(u_b_h_w_EXE),.MIO_EX(MIO_EXE));
   133	    
   134	    // TODO: implement — select ALU input A (rs1 data or PC)
   135	    MUX2T1_32 mux_A_EXE(.I0(32'b0),.I1(32'b0),.s(1'b0),.o(ALUA_EXE));
   136	
   137	    // TODO: implement — select ALU input B (rs2 data or immediate)
   138	    MUX2T1_32 mux_B_EXE(.I0(32'b0),.I1(32'b0),.s(1'b0),.o(ALUB_EXE));
   139	
   140	    ALU alu(.A(ALUA_EXE),.B(ALUB_EXE),.Control(ALUControl_EXE),
   141	        .res(ALUout_EXE),.zero(ALUzero_EXE),.overflow(ALUoverflow_EXE));
   142	    
   143	    // TODO: implement — forward mux for store data in EX stage
   144	    MUX2T1_32 mux_forward_EXE(.I0(32'b0),.I1(32'b0),.s(1'b0),.o(Dataout_EXE));
   145	
   146	
   147	    // MEM
   148	    REG_EX_MEM reg_EXE_MEM(.clk(debug_clk),.rst(rst),.EN(reg_EM_EN),.flush(reg_EM_flush),
