   160	        .mem_cs_o(ram_cs),.mem_we_o(ram_we),.mem_addr_o(ram_addr),
   161	        .mem_data_i(ram_dout),.mem_data_o(ram_din),.mem_ack_i(ram_ack),.cmu_state(cmu_state));
   162	
   163	    data_ram RAM(.clk(debug_clk),.rst(rst),.addr(ram_addr),
   164			.cs(ram_cs),.we(ram_we),.din(ram_din),.dout(ram_dout),
   165			.stall(),.ack(ram_ack),.ram_state(ram_state));
   166	        
   167	    // RAM_B data_ram(.addra(ALUout_MEM),.clka(debug_clk),.dina(Dataout_MEM), 
   168	    //     .wea(mem_w_MEM),.douta(Datain_MEM),.mem_u_b_h_w(u_b_h_w_MEM));
   169	    
   170	    assign mem_addr = MIO_MEM ? ALUout_MEM : 32'hFFFFFFFF ;
   171		assign mem_data = MIO_MEM ? Datain_MEM : 32'hAA55AA55 ;
   172	
   173	    // WB
   174	    REG_MEM_WB reg_MEM_WB(.clk(debug_clk),.rst(rst),.EN(reg_MW_EN),.IR_MEM(inst_MEM),
   175	        .PCurrent_MEM(PC_MEM),.ALUO_MEM(ALUout_MEM),.Datai(Datain_MEM),.rd_MEM(rd_MEM),
   176	        .DatatoReg_MEM(DatatoReg_MEM),.RegWrite_MEM(RegWrite_MEM),
   177	
   178	        .PCurrent_WB(PC_WB),.IR_WB(inst_WB),.ALUO_WB(ALUout_WB),.MDR_WB(Datain_WB),
   179	        .rd_WB(rd_WB),.DatatoReg_WB(DatatoReg_WB),.RegWrite_WB(RegWrite_WB));
   180	    
   181	    // TODO: implement — select writeback data (ALU result or memory data)
   182	    MUX2T1_32 mux_WB(.I0(32'b0),.I1(32'b0),.s(1'b0),.o(wt_data_WB));
   183	    
   184	    assign wb_inst = inst_WB;
   185	    assign wb_pc = PC_WB;
   186	
   187		wire [31:0] Test_signal;
   188		assign debug_data = debug_addr[5] ? Test_signal : Debug_regs;
   189		
   190	    CPUTEST    U1_3(.PC_IF(PC_IF),
   191	                    .PC_ID(PC_ID),
   192	                    .PC_EXE(PC_EXE),
   193	                    .PC_MEM(PC_MEM),
   194	                    .PC_WB(PC_WB),
   195	                    .PC_next_IF(next_PC_IF),
   196	                    .PCJump(jump_PC_ID),
   197	                    .inst_IF(inst_IF),
   198	                    .inst_ID(inst_ID),
   199	                    .inst_EXE(inst_EXE),
   200	                    .inst_MEM(inst_MEM),
   201	                    .inst_WB(inst_WB),
   202	                    .PCEN(PC_EN_IF),
   203	                    .Branch(Branch_ctrl),
   204	                    .PCSource(Branch_ctrl),
   205	                    .RS1DATA(rs1_data_reg),
   206	                    .RS2DATA(rs2_data_reg),
   207	                    .Imm32(Imm_out_ID),
   208	                    .ImmSel(ImmSel_ctrl),
   209	                    .ALUC(ALUControl_ctrl),
   210	                    .ALUSrc_A(ALUSrc_A_ctrl),
   211	                    .ALUSrc_B(ALUSrc_B_ctrl),
   212	                    .A(ALUA_EXE),
   213	                    .B(ALUB_EXE),
   214	                    .ALU_out(ALUout_MEM),
   215	                    .Datai(Datain_MEM),
   216	                    .Datao(Dataout_MEM),
