   218	                    .WR(MWR),
   219	                    .MIO(MIO_MEM),
   220	                    .WDATA(wt_data_WB),
   221	                    .DatatoReg(DatatoReg_WB),
   222	                    .RegWrite(RegWrite_WB),
   223	                    .data_hazard(reg_FD_stall),
   224	                    .control_hazard(Branch_ctrl),
