   232	endmodule=============== core/CtrlUnit.v
     1	`timescale 1ns / 1ps
     2	
     3	
     4	module CtrlUnit(
     5	    input[31:0] inst,
     6	    input cmp_res,
     7	    output Branch, ALUSrc_A, ALUSrc_B, DatatoReg, RegWrite, mem_w,
     8	        MIO, rs1use, rs2use,
     9	    output [1:0] hazard_optype,
    10	    output [2:0] ImmSel, cmp_ctrl,
    11	    output [3:0] ALUControl,
    12	    output JALR
    13	);
    14	
    15	    wire[6:0] funct7 = inst[31:25];
    16	    wire[2:0] funct3 = inst[14:12];
    17	    wire[6:0] opcode = inst[6:0];
    18	
    19	    wire Rop = opcode == 7'b0110011;
    20	    wire Iop = opcode == 7'b0010011;
    21	    wire Bop = opcode == 7'b1100011;
    22	    wire Lop = opcode == 7'b0000011;
    23	    wire Sop = opcode == 7'b0100011;
    24	
    25	    wire funct7_0  = funct7 == 7'h0;
    26	    wire funct7_32 = funct7 == 7'h20;
    27	
    28	    wire funct3_0 = funct3 == 3'h0;
    29	    wire funct3_1 = funct3 == 3'h1;
    30	    wire funct3_2 = funct3 == 3'h2;
    31	    wire funct3_3 = funct3 == 3'h3;
    32	    wire funct3_4 = funct3 == 3'h4;
    33	    wire funct3_5 = funct3 == 3'h5;
    34	    wire funct3_6 = funct3 == 3'h6;
    35	    wire funct3_7 = funct3 == 3'h7;
    36	
    37	    wire ADD  = Rop & funct3_0 & funct7_0;
    38	    wire SUB  = Rop & funct3_0 & funct7_32;
    39	    wire SLL  = Rop & funct3_1 & funct7_0;
    40	    wire SLT  = Rop & funct3_2 & funct7_0;
    41	    wire SLTU = Rop & funct3_3 & funct7_0;
    42	    wire XOR  = Rop & funct3_4 & funct7_0;
    43	    wire SRL  = Rop & funct3_5 & funct7_0;
    44	    wire SRA  = Rop & funct3_5 & funct7_32;
    45	    wire OR   = Rop & funct3_6 & funct7_0;
    46	    wire AND  = Rop & funct3_7 & funct7_0;
    47	
    48	    wire ADDI  = Iop & funct3_0;	
    49	    wire SLTI  = Iop & funct3_2;
    50	    wire SLTIU = Iop & funct3_3;
    51	    wire XORI  = Iop & funct3_4;
    52	    wire ORI   = Iop & funct3_6;
    53	    wire ANDI  = Iop & funct3_7;
    54	    wire SLLI  = Iop & funct3_1 & funct7_0;
    55	    wire SRLI  = Iop & funct3_5 & funct7_0;
    56	    wire SRAI  = Iop & funct3_5 & funct7_32;
    57	
    58	    wire BEQ = Bop & funct3_0;
    59	    wire BNE = Bop & funct3_1;
    60	    wire BLT = Bop & funct3_4;
    61	    wire BGE = Bop & funct3_5;
    62	    wire BLTU = Bop & funct3_6;
    63	    wire BGEU = Bop & funct3_7;
    64	
    65	    wire LB =  Lop & funct3_0;
    66	    wire LH =  Lop & funct3_1;
    67	    wire LW =  Lop & funct3_2;
    68	    wire LBU = Lop & funct3_4;
    69	    wire LHU = Lop & funct3_5;
    70	
    71	    wire SB = Sop & funct3_0;
    72	    wire SH = Sop & funct3_1;
    73	    wire SW = Sop & funct3_2;
    74	
    75	    wire LUI   = opcode == 7'b0110111;
    76	    wire AUIPC = opcode == 7'b0010111;
    77	
    78	    wire JAL  =  opcode == 7'b1101111;
    79	    assign JALR = (opcode == 7'b1100111) && funct3_0;
    80	
    81	    wire R_valid = AND | OR | ADD | XOR | SLL | SRL | SRA | SUB | SLT | SLTU;
    82	    wire I_valid = ANDI | ORI | ADDI | XORI | SLLI | SRLI | SRAI | SLTI | SLTIU;
    83	    wire B_valid = BEQ | BNE | BLT | BGE | BLTU | BGEU;
    84	    wire L_valid = LW | LH | LB | LHU | LBU;
    85	    wire S_valid = SW | SH | SB;
    86	
    87	    parameter Imm_type_I = 3'b001;
    88	    parameter Imm_type_B = 3'b010;
    89	    parameter Imm_type_J = 3'b011;
    90	    parameter Imm_type_S = 3'b100;
    91	    parameter Imm_type_U = 3'b101;
    92	
    93	    parameter cmp_EQ  = 3'b001;
    94	    parameter cmp_NE  = 3'b010;
    95	    parameter cmp_LT  = 3'b011;
    96	    parameter cmp_LTU = 3'b100;
    97	    parameter cmp_GE  = 3'b101;
    98	    parameter cmp_GEU = 3'b110;
    99	
   100	    parameter ALU_ADD  = 4'b0001;
   101	    parameter ALU_SUB  = 4'b0010;
   102	    parameter ALU_AND  = 4'b0011;
   103	    parameter ALU_OR   = 4'b0100;
   104	    parameter ALU_XOR  = 4'b0101;
   105	    parameter ALU_SLL  = 4'b0110;
   106	    parameter ALU_SRL  = 4'b0111;
   107	    parameter ALU_SLT  = 4'b1000;
   108	    parameter ALU_SLTU = 4'b1001;
   109	    parameter ALU_SRA  = 4'b1010;
   110	    parameter ALU_Ap4  = 4'b1011;
   111	    parameter ALU_Bout = 4'b1100;
   112	
   113	    parameter hazard_optype_ALU = 2'd1;
   114	    parameter hazard_optype_LOAD = 2'd2;
   115	    parameter hazard_optype_STORE = 2'd3;
   116	
   117	    // TODO: implement — assign Branch output
   118	    assign Branch = 1'b0;
   119	
   120	    // TODO: implement — assign ImmSel output based on instruction type
   121	    assign ImmSel = 3'b0;
   122	
   123	    // TODO: implement — assign cmp_ctrl output for branch comparisons
   124	    assign cmp_ctrl = 3'b0;
   125	
   126	    // TODO: implement — assign ALUSrc_A output
   127	    assign ALUSrc_A = 1'b0;
   128	
   129	    // TODO: implement — assign ALUSrc_B output
   130	    assign ALUSrc_B = 1'b0;
   131	
   132	    // TODO: implement — assign ALUControl output based on instruction
   133	    assign ALUControl = 4'b0;
   134	
   135	    // TODO: implement — assign DatatoReg output
   136	    assign DatatoReg = 1'b0;
   137	
   138	    // TODO: implement — assign RegWrite output
   139	    assign RegWrite = 1'b0;
   140	
   141	    // TODO: implement — assign mem_w output
   142	    assign mem_w = 1'b0;
   143	
   144	    // TODO: implement — assign MIO output
   145	    assign MIO = 1'b0;
   146	
   147	    // TODO: implement — assign rs1use output
   148	    assign rs1use = 1'b0;
   149	
   150	    // TODO: implement — assign rs2use output
   151	    assign rs2use = 1'b0;
   152	
   153	    // TODO: implement — assign hazard_optype output
   154	    assign hazard_optype = 2'b0;
   155	
   156	endmodule=============== core/ALU.v
     1	`timescale 1ns / 1ps
     2	
     3	module ALU(
     4	    input[31:0] A, B,
     5	    input[3:0] Control,
     6	    output[31:0] res,
     7	    output zero, overflow
     8	);
